UPDATE llm_provider_activation
SET active_config_id=#{configId},activation_version=activation_version+1,activated_by=#{actorId},activated_at=CURRENT_TIMESTAMP
WHERE singleton_id=1 AND activation_version=#{expectedVersion}

UPDATE llm_provider_activation
SET active_config_id=NULL,activation_version=activation_version+1,activated_by=#{actorId},activated_at=CURRENT_TIMESTAMP
WHERE singleton_id=1 AND activation_version=#{expectedVersion}

