SELECT COUNT(*) FROM llm_connectivity_checks
WHERE id=#{checkId} AND config_id=#{configId} AND fingerprint=#{fingerprint}
  AND status='SUCCEEDED' AND availability='AVAILABLE' AND finished_at>=#{notBefore}
